	cases := []struct {
		in   string
		want []string
	}{
		{"a/b/c", []string{"a", "b", "c"}},
		{"//a//b//", []string{"a", "b"}},
		{"", nil},
		{"single", []string{"single"}},
	}
	for _, c := range cases {
		got := SplitPath(c.in)
		if len(got) == 0 && len(c.want) == 0 {
			continue
		}
		if !reflect.DeepEqual(got, c.want) {
			t.Errorf("SplitPath(%q) = %v want %v", c.in, got, c.want)
		}
	}
}

func TestJoinPath(t *testing.T) {
	if got := JoinPath("a", "b", "c"); got != "a/b/c" {
