	c := newTestCache()
	c.Set("k", "v")
	if !c.Delete("k") {
		t.Fatal("expected delete to succeed")
	}
	if _, ok := c.Get("k"); ok {
		t.Fatal("key still present after delete")
	}
}

func TestKVCache_TTLExpiry(t *testing.T) {
